:root {
  --bg-card: #0f0f1a;
  --bg-panel: #1a1a2e;
  --bg-osc-a: #16213e;
  --bg-osc-b: #1e1e3a;
  --accent-primary: #7c3aed;
  --accent-secondary: #06b6d4;
  --accent-green: #10b981;
  --text-primary: #e2e8f0;
  --text-muted: #64748b;
  --text-label: #94a3b8;
  --border-subtle: #2d2d4e;
  --btn-save-bg: #7c3aed;
  --btn-play-bg: #06b6d4;
  --env-bar-color: #7c3aed;
}

.synth-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  width: 476px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.synth-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.synth-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--accent-primary);
  text-transform: uppercase;
  display: block;
  margin-bottom: 1px;
}

.synth-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.synth-version {
  font-size: 11px;
  font-weight: 400;
  color: var(--text-muted);
}

.synth-badge {
  background: var(--accent-primary);
  color: var(--text-primary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 3px 9px;
  border-radius: 5px;
}

.synth-body {
  display: grid;
  grid-template-columns: 1fr 72px 1fr;
  gap: 8px;
}

.panel-title {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--text-muted);
  text-transform: uppercase;
  margin: 0 0 6px 0;
}

.osc-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  padding: 8px;
}

.osc-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.osc-block {
  border-radius: 7px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.osc-a {
  background: var(--bg-osc-a);
  border: 1px solid var(--accent-primary);
}

.osc-b {
  background: var(--bg-osc-b);
  border: 1px solid var(--accent-secondary);
}

.osc-id {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-label);
}

.osc-a .osc-id { color: var(--accent-primary); }
.osc-b .osc-id { color: var(--accent-secondary); }

.wave-display {
  height: 22px;
  display: flex;
  align-items: center;
}

.wave-svg {
  width: 100%;
  height: 100%;
}

.osc-a .wave-svg { color: var(--accent-primary); }
.osc-b .wave-svg { color: var(--accent-secondary); }

.osc-stats {
  display: flex;
  gap: 6px;
}

.stat-item {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-primary);
}

.stat-item em {
  font-style: normal;
  font-size: 8px;
  color: var(--text-muted);
  margin-left: 1px;
}

.env-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  padding: 8px;
  display: flex;
  flex-direction: column;
}

.env-bars {
  display: flex;
  gap: 4px;
  flex: 1;
  align-items: flex-end;
}

.env-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex: 1;
}

.env-bar-wrap {
  width: 100%;
  height: 100px;
  background: var(--bg-card);
  border-radius: 3px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}

.env-bar {
  width: 100%;
  height: var(--h);
  background: var(--env-bar-color);
  border-radius: 2px 2px 0 0;
  opacity: 0.85;
}

.env-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--text-muted);
}

.fx-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  padding: 8px;
}

.fx-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.fx-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 7px;
  border-radius: 5px;
  background: var(--bg-card);
}

.fx-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.fx-on .fx-dot { background: var(--accent-green); }
.fx-off .fx-dot { background: var(--text-muted); }

.fx-name {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-label);
  flex: 1;
}

.fx-off .fx-name { color: var(--text-muted); }

.fx-val {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-green);
}

.fx-off .fx-val { color: var(--text-muted); }

.synth-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
  padding-top: 8px;
}

.footer-meta {
  display: flex;
  gap: 5px;
}

.meta-chip {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 20px;
  padding: 2px 8px;
  font-size: 10px;
  font-weight: 600;
  color: var(--text-label);
}

.footer-actions {
  display: flex;
  gap: 6px;
}

.btn-save {
  background: transparent;
  border: 1px solid var(--btn-save-bg);
  color: var(--accent-primary);
  border-radius: 7px;
  padding: 5px 12px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}

.btn-play {
  background: var(--btn-play-bg);
  border: none;
  color: var(--bg-card);
  border-radius: 7px;
  padding: 5px 12px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}
